1	package v1
2	
3	import (
4		"context"
5		"fmt"
6	
7		"github.com/pkg/errors"
8		"google.golang.org/grpc/codes"
9		"google.golang.org/grpc/status"
10		"google.golang.org/protobuf/types/known/emptypb"
11	
12		v1pb "github.com/usememos/memos/proto/gen/api/v1"
13		storepb "github.com/usememos/memos/proto/gen/store"
14		"github.com/usememos/memos/store"
15	)
16	
17	func (s *APIV1Service) CreateIdentityProvider(ctx context.Context, request *v1pb.CreateIdentityProviderRequest) (*v1pb.IdentityProvider, error) {
18		currentUser, err := s.fetchCurrentUser(ctx)
19		if err != nil {
20			return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
21		}
22		if currentUser == nil {
23			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
24		}
25		if currentUser.Role != store.RoleAdmin {
26			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
27		}
28	
29		idpUID, err := ValidateAndGenerateUID(request.IdentityProviderId)
30		if err != nil {
31			return nil, err
32		}
33		if s.Store.IsIdentityProviderDeploymentConfigured(idpUID) {
34			return nil, status.Errorf(codes.FailedPrecondition, "identity provider %q is configured by the deployment", idpUID)
35		}
36	
37		storeIdp := convertIdentityProviderToStore(request.IdentityProvider)
38		storeIdp.Uid = idpUID
39	
40		identityProvider, err := s.Store.CreateIdentityProvider(ctx, storeIdp)
41		if err != nil {
42			return nil, status.Errorf(codes.Internal, "failed to create identity provider, error: %+v", err)
43		}
44		return convertIdentityProviderFromStore(identityProvider), nil
45	}
46	
47	func (s *APIV1Service) ListIdentityProviders(ctx context.Context, _ *v1pb.ListIdentityProvidersRequest) (*v1pb.ListIdentityProvidersResponse, error) {
48		identityProviders, err := s.Store.ListIdentityProviders(ctx, &store.FindIdentityProvider{})
49		if err != nil {
50			return nil, status.Errorf(codes.Internal, "failed to list identity providers, error: %+v", err)
51		}
52	
53		response := &v1pb.ListIdentityProvidersResponse{
54			IdentityProviders: []*v1pb.IdentityProvider{},
55		}
56		for _, identityProvider := range identityProviders {
57			response.IdentityProviders = append(response.IdentityProviders, convertIdentityProviderFromStore(identityProvider))
58		}
59		return response, nil
60	}
61	
62	func (s *APIV1Service) GetIdentityProvider(ctx context.Context, request *v1pb.GetIdentityProviderRequest) (*v1pb.IdentityProvider, error) {
63		uid, err := ExtractIdentityProviderUIDFromName(request.Name)
64		if err != nil {
65			return nil, status.Errorf(codes.InvalidArgument, "invalid identity provider name: %v", err)
66		}
67		identityProvider, err := s.Store.GetIdentityProvider(ctx, &store.FindIdentityProvider{
68			UID: &uid,
69		})
70		if err != nil {
71			return nil, status.Errorf(codes.Internal, "failed to get identity provider, error: %+v", err)
72		}
73		if identityProvider == nil {
74			return nil, status.Errorf(codes.NotFound, "identity provider not found")
75		}
76	
77		return convertIdentityProviderFromStore(identityProvider), nil
78	}
79	
80	func (s *APIV1Service) UpdateIdentityProvider(ctx context.Context, request *v1pb.UpdateIdentityProviderRequest) (*v1pb.IdentityProvider, error) {
81		currentUser, err := s.fetchCurrentUser(ctx)
82		if err != nil {
83			return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
84		}
85		if currentUser == nil {
86			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
87		}
88		if currentUser.Role != store.RoleAdmin {
89			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
90		}
91	
92		if request.UpdateMask == nil || len(request.UpdateMask.Paths) == 0 {
93			return nil, status.Errorf(codes.InvalidArgument, "update_mask is required")
94		}
95	
96		uid, err := ExtractIdentityProviderUIDFromName(request.IdentityProvider.Name)
97		if err != nil {
98			return nil, status.Errorf(codes.InvalidArgument, "invalid identity provider name: %v", err)
99		}
100		if s.Store.IsIdentityProviderDeploymentConfigured(uid) {
101			return nil, status.Errorf(codes.FailedPrecondition, "identity provider %q is configured by the deployment", uid)
102		}
103	
104		// Look up the IdP by UID to get the internal ID for update.
105		existing, err := s.Store.GetStoredIdentityProvider(ctx, &store.FindIdentityProvider{UID: &uid})
106		if err != nil {
107			return nil, status.Errorf(codes.Internal, "failed to get identity provider, error: %+v", err)
108		}
109		if existing == nil {
110			return nil, status.Errorf(codes.NotFound, "identity provider not found")
111		}
112	
113		update := &store.UpdateIdentityProviderV1{
114			ID:   existing.Id,
115			Type: storepb.IdentityProvider_Type(storepb.IdentityProvider_Type_value[request.IdentityProvider.Type.String()]),
116		}
117		for _, field := range request.UpdateMask.Paths {
118			switch field {
119			case "title":
120				update.Name = &request.IdentityProvider.Title
121			case "identifier_filter":
122				update.IdentifierFilter = &request.IdentityProvider.IdentifierFilter
123			case "config":
124				update.Config = convertIdentityProviderConfigToStore(request.IdentityProvider.Type, request.IdentityProvider.Config)
125			default:
126				// Ignore unsupported fields
127			}
128		}
129	
130		// Preserve write-only credential when the caller sends an empty value.
131		if update.Config != nil {
132			if oauth2Config := update.Config.GetOauth2Config(); oauth2Config != nil && oauth2Config.ClientSecret == "" {
133				if existingOAuth := existing.Config.GetOauth2Config(); existingOAuth != nil {
134					oauth2Config.ClientSecret = existingOAuth.ClientSecret
135				}
136			}
137		}
138	
139		identityProvider, err := s.Store.UpdateIdentityProvider(ctx, update)
140		if err != nil {
141			return nil, status.Errorf(codes.Internal, "failed to update identity provider, error: %+v", err)
142		}
143		return convertIdentityProviderFromStore(identityProvider), nil
144	}
145	
146	func (s *APIV1Service) DeleteIdentityProvider(ctx context.Context, request *v1pb.DeleteIdentityProviderRequest) (*emptypb.Empty, error) {
147		currentUser, err := s.fetchCurrentUser(ctx)
148		if err != nil {
149			return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
150		}
151		if currentUser == nil {
152			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
153		}
154		if currentUser.Role != store.RoleAdmin {
155			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
156		}
157	
158		uid, err := ExtractIdentityProviderUIDFromName(request.Name)
159		if err != nil {
160			return nil, status.Errorf(codes.InvalidArgument, "invalid identity provider name: %v", err)
161		}
162		if s.Store.IsIdentityProviderDeploymentConfigured(uid) {
163			return nil, status.Errorf(codes.FailedPrecondition, "identity provider %q is configured by the deployment", uid)
164		}
165	
166		// Look up the IdP by UID to get the internal ID for deletion.
167		identityProvider, err := s.Store.GetStoredIdentityProvider(ctx, &store.FindIdentityProvider{UID: &uid})
168		if err != nil {
169			return nil, status.Errorf(codes.Internal, "failed to check identity provider existence: %v", err)
170		}
171		if identityProvider == nil {
172			return nil, status.Errorf(codes.NotFound, "identity provider not found")
173		}
174	
175		if err := s.Store.DeleteIdentityProviderSafely(ctx, &store.DeleteIdentityProvider{ID: identityProvider.Id}); err != nil {
176			if errors.Is(err, store.ErrUnsafeAuthenticationConfiguration) {
177				return nil, status.Error(codes.FailedPrecondition, err.Error())
178			}
179			return nil, status.Errorf(codes.Internal, "failed to delete identity provider, error: %+v", err)
180		}
181		return &emptypb.Empty{}, nil
182	}
183	
184	func convertIdentityProviderFromStore(identityProvider *storepb.IdentityProvider) *v1pb.IdentityProvider {
185		temp := &v1pb.IdentityProvider{
186			Name:             fmt.Sprintf("%s%s", IdentityProviderNamePrefix, identityProvider.Uid),
187			Title:            identityProvider.Name,
188			IdentifierFilter: identityProvider.IdentifierFilter,
189			Type:             v1pb.IdentityProvider_Type(v1pb.IdentityProvider_Type_value[identityProvider.Type.String()]),
190		}
191		if identityProvider.Type == storepb.IdentityProvider_OAUTH2 {
192			oauth2Config := identityProvider.Config.GetOauth2Config()
193			temp.Config = &v1pb.IdentityProviderConfig{
194				Config: &v1pb.IdentityProviderConfig_Oauth2Config{
195					Oauth2Config: &v1pb.OAuth2Config{
196						ClientId: oauth2Config.ClientId,
197						// ClientSecret is write-only: never returned in responses.
198						AuthUrl:     oauth2Config.AuthUrl,
199						TokenUrl:    oauth2Config.TokenUrl,
200						UserInfoUrl: oauth2Config.UserInfoUrl,
201						Scopes:      oauth2Config.Scopes,
202						FieldMapping: &v1pb.FieldMapping{
203							Identifier:  oauth2Config.FieldMapping.Identifier,
204							DisplayName: oauth2Config.FieldMapping.DisplayName,
205							Email:       oauth2Config.FieldMapping.Email,
206							AvatarUrl:   oauth2Config.FieldMapping.AvatarUrl,
207						},
208					},
209				},
210			}
211		}
212		return temp
213	}
214	
215	func convertIdentityProviderToStore(identityProvider *v1pb.IdentityProvider) *storepb.IdentityProvider {
216		temp := &storepb.IdentityProvider{
217			Name:             identityProvider.Title,
218			IdentifierFilter: identityProvider.IdentifierFilter,
219			Type:             storepb.IdentityProvider_Type(storepb.IdentityProvider_Type_value[identityProvider.Type.String()]),
220			Config:           convertIdentityProviderConfigToStore(identityProvider.Type, identityProvider.Config),
221		}
222		return temp
223	}
224	
225	func convertIdentityProviderConfigToStore(identityProviderType v1pb.IdentityProvider_Type, config *v1pb.IdentityProviderConfig) *storepb.IdentityProviderConfig {
226		if identityProviderType == v1pb.IdentityProvider_OAUTH2 {
227			oauth2Config := config.GetOauth2Config()
228			return &storepb.IdentityProviderConfig{
229				Config: &storepb.IdentityProviderConfig_Oauth2Config{
230					Oauth2Config: &storepb.OAuth2Config{
231						ClientId:     oauth2Config.ClientId,
232						ClientSecret: oauth2Config.ClientSecret,
233						AuthUrl:      oauth2Config.AuthUrl,
234						TokenUrl:     oauth2Config.TokenUrl,
235						UserInfoUrl:  oauth2Config.UserInfoUrl,
236						Scopes:       oauth2Config.Scopes,
237						FieldMapping: &storepb.FieldMapping{
238							Identifier:  oauth2Config.FieldMapping.Identifier,
239							DisplayName: oauth2Config.FieldMapping.DisplayName,
240							Email:       oauth2Config.FieldMapping.Email,
241							AvatarUrl:   oauth2Config.FieldMapping.AvatarUrl,
242						},
243					},
244				},
245			}
246		}
247		return nil
248	}
